            else:
                out.append("      SPEC none")
            for b in acc_by.get(accn,[]):
                an,am,ad=ext(b,'patient-name'),ext(b,'patient-mrn'),ext(b,'patient-dob')
                mism=(am!=pt['identifier'][0]['value']) or (ad!=pt['birthDate'])
                out.append(f"      ACC  {b['id']} acc={accn} {an}/{am}/{ad} recv={ext(b,'received')} auth={b.get('author',{}).get('display')} {'**ACC-MISMATCH**' if mism else ''}")
        elif f=='Med':
            out.append(f"  {t} MED {r['id']} {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} st={r['status']} note={'; '.join(n['text'] for n in r.get('note',[]))} perf={[x['actor']['display'] for x in r.get('performer',[])]}")
        elif f=='Disp':
            out.append(f"  {t} DISP {r['id']} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} {[x['text'] for x in r.get('dosageInstruction',[])]} note={'; '.join(n['text'] for n in r.get('note',[]))}")
        elif f=='Doc':
            out.append(f"  {t} DOC {r['id']} [{r['type']['text']}] auth={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')}\n      {r['description']}")
        elif f=='Task':
            out.append(f"  {t} TASK {r['id']} {r['code']['coding'][0]['code']} st={r['status']} focus={r['focus']['reference']} :: {r['description']}")
        elif f=='Allergy':
            out.append(f"  {t} ALLERGY {r['id']} {r['code']['text']} {[m['text'] for x in r.get('reaction',[]) for m in x['manifestation']]}")
        elif f=='Spec':
            pass
    return '\n'.join(out)
if __name__=='__main__':
    ids=sys.argv[1:] if len(sys.argv)>1 else sorted(P)
    for p in ids: print(rep(p)); print()
